/* ===== CSS Variables ===== */
:root {
  --color-primary: #00824A;
  --color-primary-hover: #006B3D;
  --color-primary-light: #E6F5EE;
  --color-dark: #32462F;
  --color-dark-light: #4A6645;
  --color-cream: #F3CEA1;
  --color-cream-light: #FDF3E5;
  --color-white: #FFFFFF;
  --color-off-white: #F9F6F0;
  --color-bg: #FAFAF8;
  --color-text: #1a1a1a;
  --color-text-secondary: #555;
  --color-text-light: #777;
  --color-border: #E0DED5;
  --color-border-light: #EEECE5;
  --color-shadow: rgba(0, 0, 0, 0.06);
  --color-shadow-md: rgba(0, 0, 0, 0.1);
  --color-overlay: rgba(0, 0, 0, 0.4);
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-heading: 'DM Serif Display', Georgia, 'Times New Roman', serif;
  --font-display: 'DM Sans', 'Inter', sans-serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 3px var(--color-shadow);
  --shadow-md: 0 4px 12px var(--color-shadow-md);
  --shadow-lg: 0 8px 30px var(--color-shadow-md);
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1280px;
  --header-height: 72px;
}

/* ===== Reset ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  color: var(--color-text);
  background-color: var(--color-white);
  line-height: 1.6;
  min-height: 100vh;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

input, select {
  font-family: inherit;
  font-size: inherit;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  line-height: 1.2;
  font-weight: 400;
}

h1 { font-size: 3.5rem; }
h2 { font-size: 2.5rem; }
h3 { font-size: 1.75rem; }
h4 { font-size: 1.25rem; }

.display-text {
  font-family: var(--font-display);
  font-weight: 600;
}

.body-lg { font-size: 1.125rem; }
.body-sm { font-size: 0.875rem; }
.body-xs { font-size: 0.75rem; }

.text-primary { color: var(--color-primary); }
.text-dark { color: var(--color-dark); }
.text-secondary { color: var(--color-text-secondary); }
.text-light { color: var(--color-text-light); }
.text-cream { color: var(--color-cream); }

.text-center { text-align: center; }
.text-left { text-align: left; }
.text-right { text-align: right; }

.font-body { font-family: var(--font-body); }
.font-display { font-family: var(--font-display); }

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.938rem;
  transition: all var(--transition-base);
  white-space: nowrap;
  border: 2px solid transparent;
  line-height: 1.2;
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background-color: transparent;
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.btn-outline:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

.btn-outline-white {
  background-color: transparent;
  border-color: var(--color-white);
  color: var(--color-white);
}

.btn-outline-white:hover {
  background-color: var(--color-white);
  color: var(--color-dark);
}

.btn-dark {
  background-color: var(--color-dark);
  color: var(--color-white);
}

.btn-dark:hover {
  background-color: var(--color-dark-light);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.813rem;
}

.btn-lg {
  padding: 16px 36px;
  font-size: 1.063rem;
}

.btn-link {
  padding: 0;
  background: none;
  border: none;
  color: var(--color-primary);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.btn-link:hover {
  color: var(--color-primary-hover);
}

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 80px 0;
}

.section-sm {
  padding: 48px 0;
}

.section-lg {
  padding: 120px 0;
}

.section-header {
  text-align: center;
  margin-bottom: 48px;
}

.section-header h2 {
  margin-bottom: 12px;
}

.section-header p {
  color: var(--color-text-secondary);
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto;
}

/* ===== Grid Helpers ===== */
.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* ===== Card ===== */
.card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-border-light);
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-img {
  border-radius: var(--radius-md);
  overflow: hidden;
  aspect-ratio: 3/2;
  background-color: var(--color-off-white);
}

.card-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ===== Header ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border-light);
  height: var(--header-height);
  box-shadow: 0 1px 4px rgba(0,0,0,0.03);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  color: var(--color-dark);
}

.header-logo .logo-icon {
  width: 36px;
  height: 36px;
  background: var(--color-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.2rem;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}

.header-nav a {
  padding: 8px 16px;
  border-radius: var(--radius-full);
  font-weight: 500;
  font-size: 0.938rem;
  color: var(--color-text);
  transition: all var(--transition-fast);
}

.header-nav a:hover,
.header-nav a.active {
  color: var(--color-primary);
  background: var(--color-primary-light);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header-actions .btn {
  padding: 8px 20px;
  font-size: 0.875rem;
}

.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-dark);
  border-radius: 2px;
  transition: var(--transition-base);
}

.mobile-menu-btn.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}
.mobile-menu-btn.active span:nth-child(2) {
  opacity: 0;
}
.mobile-menu-btn.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* ===== Cookie Banner ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--color-white);
  border-top: 2px solid var(--color-cream);
  padding: 20px 24px;
  z-index: 200;
  box-shadow: 0 -4px 20px var(--color-shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  flex-wrap: wrap;
  animation: slideUp 0.4s var(--transition-slow);
}

.cookie-banner.hidden {
  display: none;
}

@keyframes slideUp {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}

.cookie-banner-content h3 {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  margin-bottom: 4px;
}

.cookie-banner-content p {
  color: var(--color-text-secondary);
  font-size: 0.875rem;
  max-width: 600px;
}

.cookie-banner-actions {
  display: flex;
  gap: 12px;
}

/* ===== Hero Section ===== */
.hero {
  background: linear-gradient(135deg, var(--color-dark) 0%, #1a3a1a 100%);
  color: var(--color-white);
  padding: 100px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0,130,74,0.3) 0%, transparent 70%);
  border-radius: 50%;
}

.hero::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -5%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(243,206,161,0.15) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 600px;
}

.hero h1 {
  font-size: 4rem;
  margin-bottom: 16px;
  line-height: 1.1;
}

.hero .hero-subtitle {
  font-size: 1.25rem;
  color: rgba(255,255,255,0.85);
  margin-bottom: 32px;
  font-family: var(--font-display);
}

.hero-image {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 45%;
  height: 80%;
  background: var(--color-cream-light);
  border-radius: var(--radius-xl) 0 0 var(--radius-xl);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 6rem;
}

/* ===== Featured / Promo Sections ===== */
.feature-section {
  padding: 80px 0;
}

.feature-section.alt {
  background-color: var(--color-off-white);
}

.feature-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feature-grid.reverse {
  direction: rtl;
}

.feature-grid.reverse > * {
  direction: ltr;
}

.feature-image {
  border-radius: var(--radius-xl);
  overflow: hidden;
  aspect-ratio: 4/3;
  background-color: var(--color-cream-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

.feature-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.feature-text h2 {
  margin-bottom: 16px;
}

.feature-text p {
  color: var(--color-text-secondary);
  font-size: 1.125rem;
  margin-bottom: 24px;
  line-height: 1.7;
}

.feature-text .btn {
  margin-top: 8px;
}

/* ===== Seasonal Highlight ===== */
.seasonal-card {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-dark) 100%);
  color: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 56px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  overflow: hidden;
  position: relative;
}

.seasonal-card::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(255,255,255,0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.seasonal-card.reverse {
  background: linear-gradient(135deg, var(--color-cream) 0%, #E8B87A 100%);
  color: var(--color-dark);
}

.seasonal-card.reverse::before {
  background: radial-gradient(circle, rgba(255,255,255,0.3) 0%, transparent 70%);
}

.seasonal-card-content {
  position: relative;
  z-index: 1;
}

.seasonal-card-content h2 {
  font-size: 2.25rem;
  margin-bottom: 12px;
}

.seasonal-card-content p {
  font-size: 1.063rem;
  opacity: 0.9;
  margin-bottom: 24px;
  line-height: 1.7;
}

.seasonal-card-image {
  aspect-ratio: 1;
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 6rem;
  position: relative;
  z-index: 1;
}

.seasonal-card.reverse .seasonal-card-image {
  background: rgba(0,0,0,0.06);
}

.seasonal-card .btn {
  background: var(--color-white);
  color: var(--color-dark);
  border-color: var(--color-white);
}

.seasonal-card .btn:hover {
  background: transparent;
  color: var(--color-white);
  border-color: var(--color-white);
}

.seasonal-card.reverse .btn {
  background: var(--color-dark);
  color: var(--color-white);
  border-color: var(--color-dark);
}

.seasonal-card.reverse .btn:hover {
  background: transparent;
  color: var(--color-dark);
  border-color: var(--color-dark);
}

/* ===== Menu Page ===== */
.breadcrumb {
  padding: 16px 0;
  color: var(--color-text-light);
  font-size: 0.875rem;
}

.breadcrumb a {
  color: var(--color-text-secondary);
}

.breadcrumb a:hover {
  color: var(--color-primary);
}

.breadcrumb span {
  margin: 0 8px;
}

.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 48px;
  padding: 40px 0 80px;
}

.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + 24px);
  align-self: start;
}

.menu-sidebar h3 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-light);
  margin-bottom: 12px;
  margin-top: 28px;
}

.menu-sidebar h3:first-child {
  margin-top: 0;
}

.menu-sidebar a {
  display: block;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.938rem;
  color: var(--color-text-secondary);
  transition: all var(--transition-fast);
  margin-bottom: 2px;
}

.menu-sidebar a:hover,
.menu-sidebar a.active {
  color: var(--color-primary);
  background: var(--color-primary-light);
  font-weight: 500;
}

.menu-content h2 {
  margin-bottom: 8px;
}

.menu-content .category-desc {
  color: var(--color-text-secondary);
  margin-bottom: 32px;
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
  margin-bottom: 56px;
}

.menu-item {
  display: flex;
  gap: 16px;
  padding: 16px;
  border-radius: var(--radius-md);
  transition: all var(--transition-base);
}

.menu-item:hover {
  background: var(--color-off-white);
}

.menu-item-img {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-sm);
  background: var(--color-cream-light);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  overflow: hidden;
}

.menu-item-info h4 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1rem;
  margin-bottom: 4px;
}

.menu-item-info p {
  font-size: 0.813rem;
  color: var(--color-text-light);
  line-height: 1.4;
}

/* ===== Rewards Page ===== */
.rewards-hero {
  background: linear-gradient(135deg, var(--color-dark) 0%, #1a3320 100%);
  color: var(--color-white);
  padding: 80px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.rewards-hero::before {
  content: '';
  position: absolute;
  top: -40%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(0,130,74,0.25) 0%, transparent 70%);
  border-radius: 50%;
}

.rewards-hero-content {
  position: relative;
  z-index: 1;
}

.rewards-hero h1 {
  font-size: 3.5rem;
  margin-bottom: 16px;
}

.rewards-hero .lead {
  font-size: 1.25rem;
  opacity: 0.85;
  margin-bottom: 32px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 40px;
  text-align: center;
}

.step-card {
  padding: 32px 24px;
}

.step-number {
  width: 56px;
  height: 56px;
  background: var(--color-primary-light);
  color: var(--color-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0 auto 20px;
  font-family: var(--font-display);
}

.step-card h3 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.125rem;
  margin-bottom: 8px;
}

.step-card p {
  color: var(--color-text-secondary);
  font-size: 0.938rem;
}

/* Tier Cards */
.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.tier-card {
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  text-align: center;
  border: 2px solid var(--color-border-light);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.tier-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.tier-card.featured {
  border-color: var(--color-dark);
  background: var(--color-dark);
  color: var(--color-white);
}

.tier-card.featured .tier-benefit {
  color: rgba(255,255,255,0.8);
}

.tier-card.featured .tier-star {
  color: var(--color-cream);
}

.tier-badge {
  display: inline-block;
  padding: 4px 16px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 16px;
  background: var(--color-primary-light);
  color: var(--color-primary);
}

.tier-card.featured .tier-badge {
  background: rgba(255,255,255,0.2);
  color: var(--color-white);
}

.tier-card h3 {
  font-size: 1.5rem;
  margin-bottom: 8px;
}

.tier-card.featured h3 {
  color: var(--color-white);
}

.tier-star {
  font-size: 0.875rem;
  color: var(--color-primary);
  font-weight: 600;
  margin-bottom: 16px;
}

.tier-benefits {
  text-align: left;
}

.tier-benefit {
  padding: 8px 0;
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  border-bottom: 1px solid var(--color-border-light);
  display: flex;
  align-items: center;
  gap: 8px;
}

.tier-benefit:last-child {
  border-bottom: none;
}

.tier-benefit::before {
  content: '✓';
  color: var(--color-primary);
  font-weight: 700;
  font-size: 0.75rem;
}

.tier-card.featured .tier-benefit {
  border-color: rgba(255,255,255,0.15);
}

.tier-card.featured .tier-benefit::before {
  color: var(--color-cream);
}

/* Redemption Tabs */
.redemption-section {
  background: var(--color-off-white);
}

.redemption-tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 40px;
}

.redemption-tab {
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.938rem;
  color: var(--color-text-secondary);
  background: var(--color-white);
  border: 2px solid var(--color-border);
  transition: all var(--transition-base);
}

.redemption-tab:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.redemption-tab.active {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
  box-shadow: 0 4px 12px rgba(0,130,74,0.3);
}

.redemption-content {
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
}

.redemption-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.redemption-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.redemption-panel .star-count {
  font-size: 3rem;
  font-family: var(--font-heading);
  color: var(--color-primary);
  margin-bottom: 8px;
}

.redemption-panel h3 {
  font-family: var(--font-display);
  font-weight: 600;
  margin-bottom: 8px;
}

.redemption-panel .reward-value {
  display: inline-block;
  padding: 4px 16px;
  background: var(--color-cream-light);
  color: var(--color-dark);
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.875rem;
  margin-bottom: 16px;
}

.redemption-panel p {
  color: var(--color-text-secondary);
  font-size: 1.063rem;
}

/* Partnerships */
.partnerships-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.partner-card {
  padding: 32px;
  border-radius: var(--radius-lg);
  background: var(--color-white);
  display: flex;
  gap: 20px;
  align-items: flex-start;
  border: 1px solid var(--color-border-light);
  transition: all var(--transition-base);
}

.partner-card:hover {
  box-shadow: var(--shadow-md);
}

.partner-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-md);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.partner-delta {
  background: #E6F0FA;
  color: #003A70;
}

.partner-marriott {
  background: #FDF0E0;
  color: #A0522D;
}

/* ===== Gift Cards Page ===== */
.gift-hero {
  background: linear-gradient(135deg, #1a3320 0%, var(--color-dark) 100%);
  color: var(--color-white);
  padding: 80px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.gift-hero::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(0,130,74,0.3) 0%, transparent 70%);
  border-radius: 50%;
}

.gift-hero h1 {
  font-size: 3.5rem;
  margin-bottom: 16px;
  position: relative;
  z-index: 1;
}

.gift-hero .lead {
  font-size: 1.25rem;
  opacity: 0.85;
  margin-bottom: 32px;
  position: relative;
  z-index: 1;
}

/* Carousels */
.carousel-section {
  margin-bottom: 48px;
}

.carousel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}

.carousel-header h2 {
  font-size: 1.75rem;
}

.carousel-nav {
  display: flex;
  gap: 8px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  color: var(--color-text);
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  background: var(--color-primary-light);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-track-wrapper {
  overflow: hidden;
  border-radius: var(--radius-md);
}

.carousel-track {
  display: flex;
  gap: 20px;
  transition: transform var(--transition-slow);
}

.gift-card {
  min-width: 220px;
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  cursor: pointer;
  background: var(--color-white);
  border: 1px solid var(--color-border-light);
}

.gift-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.gift-card-image {
  aspect-ratio: 3/2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  color: var(--color-white);
}

.gift-card-label {
  padding: 12px 16px;
  font-weight: 600;
  font-size: 0.875rem;
  text-align: center;
}

.category-carousel {
  margin-bottom: 56px;
}

.category-carousel h3 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.375rem;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--color-border-light);
}

.category-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--color-border-light);
}

.category-header h3 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.375rem;
  margin: 0;
  padding: 0;
  border: none;
}

.category-carousel .carousel-nav {
  margin: 0;
}

.business-gifting {
  background: var(--color-off-white);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  margin: 64px 0;
}

.business-gifting h2 {
  margin-bottom: 12px;
}

.business-gifting p {
  color: var(--color-text-secondary);
  font-size: 1.063rem;
  margin-bottom: 24px;
  line-height: 1.7;
}

.bg-image {
  aspect-ratio: 16/10;
  background: var(--color-cream-light);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

.egift-info {
  background: var(--color-primary-light);
  border-radius: var(--radius-xl);
  padding: 40px;
  margin-bottom: 64px;
}

.egift-info h3 {
  color: var(--color-primary);
  margin-bottom: 8px;
}

.egift-info p {
  color: var(--color-text-secondary);
  font-size: 1rem;
  line-height: 1.7;
}

/* FAQ */
.faq-section {
  max-width: 800px;
  margin: 0 auto 64px;
}

.faq-item {
  border-bottom: 1px solid var(--color-border-light);
  padding: 20px 0;
}

.faq-item summary {
  font-weight: 600;
  cursor: pointer;
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1.063rem;
}

.faq-item summary::-webkit-details-marker {
  display: none;
}

.faq-item summary::after {
  content: '+';
  font-size: 1.5rem;
  color: var(--color-primary);
  font-weight: 300;
  transition: transform var(--transition-base);
}

.faq-item[open] summary::after {
  content: '−';
}

.faq-item .faq-answer {
  padding-top: 12px;
  color: var(--color-text-secondary);
  font-size: 0.938rem;
  line-height: 1.6;
}

/* ===== Store Locator ===== */
.locator-layout {
  display: grid;
  grid-template-columns: 420px 1fr;
  gap: 0;
  min-height: calc(100vh - var(--header-height));
}

.locator-sidebar {
  border-right: 1px solid var(--color-border-light);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  max-height: calc(100vh - var(--header-height));
  overflow: hidden;
}

.locator-search {
  position: relative;
}

.locator-search input {
  width: 100%;
  padding: 14px 16px 14px 44px;
  border-radius: var(--radius-full);
  border: 2px solid var(--color-border);
  font-size: 0.938rem;
  background: var(--color-off-white);
  transition: all var(--transition-base);
}

.locator-search input:focus {
  outline: none;
  border-color: var(--color-primary);
  background: var(--color-white);
  box-shadow: 0 0 0 4px rgba(0,130,74,0.1);
}

.locator-search .search-icon {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-text-light);
  font-size: 1rem;
}

.locator-search-suggestions {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  background: var(--color-white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--color-border-light);
  z-index: 50;
  display: none;
}

.locator-search-suggestions.active {
  display: block;
}

.locator-search-suggestions .suggestion {
  padding: 12px 16px;
  cursor: pointer;
  font-size: 0.875rem;
  border-bottom: 1px solid var(--color-border-light);
  display: flex;
  align-items: center;
  gap: 10px;
  transition: background var(--transition-fast);
}

.locator-search-suggestions .suggestion:last-child {
  border-bottom: none;
}

.locator-search-suggestions .suggestion:hover {
  background: var(--color-primary-light);
}

.locator-controls {
  display: flex;
  gap: 12px;
}

.order-type-toggle {
  display: flex;
  background: var(--color-off-white);
  border-radius: var(--radius-full);
  padding: 4px;
  flex: 1;
}

.order-type-btn {
  flex: 1;
  padding: 10px 16px;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  transition: all var(--transition-base);
}

.order-type-btn.active {
  background: var(--color-white);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.filter-btn {
  padding: 10px 20px;
  border-radius: var(--radius-full);
  border: 2px solid var(--color-border);
  font-weight: 600;
  font-size: 0.875rem;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--color-text);
  transition: all var(--transition-base);
  background: var(--color-white);
}

.filter-btn:hover,
.filter-btn.active {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.filter-panel {
  background: var(--color-white);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border-light);
  padding: 20px;
  display: none;
  flex-direction: column;
  gap: 16px;
}

.filter-panel.active {
  display: flex;
}

.filter-panel h4 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-light);
  margin-bottom: 4px;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.938rem;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  width: 18px;
  height: 18px;
  accent-color: var(--color-primary);
}

.locator-results {
  flex: 1;
  overflow-y: auto;
}

.locator-result {
  padding: 16px;
  border-bottom: 1px solid var(--color-border-light);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.locator-result:hover {
  background: var(--color-off-white);
}

.locator-result h4 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1rem;
  margin-bottom: 4px;
}

.locator-result .store-address {
  font-size: 0.813rem;
  color: var(--color-text-light);
  margin-bottom: 6px;
}

.locator-result .store-meta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.locator-result .store-feature {
  font-size: 0.75rem;
  color: var(--color-primary);
  background: var(--color-primary-light);
  padding: 2px 10px;
  border-radius: var(--radius-full);
  font-weight: 500;
}

.locator-result .store-status {
  font-size: 0.813rem;
  font-weight: 600;
}

.locator-result .store-status.open {
  color: var(--color-primary);
}

.locator-result .store-status.closed {
  color: #c0392b;
}

.store-distance {
  font-size: 0.813rem;
  color: var(--color-text-light);
}

.locator-map {
  background: #e8e4dd;
  position: relative;
  min-height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-light);
  font-size: 1.5rem;
}

.locator-map-inner {
  text-align: center;
}

.locator-map-pin {
  position: absolute;
  width: 24px;
  height: 24px;
  background: var(--color-primary);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
}

.locator-map-pin::after {
  content: '';
  position: absolute;
  top: 4px;
  left: 4px;
  width: 16px;
  height: 16px;
  background: var(--color-white);
  border-radius: 50%;
}

/* ===== Footer ===== */
.site-footer {
  background: var(--color-dark);
  color: var(--color-white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 0.938rem;
  margin-bottom: 16px;
}

.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.813rem;
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--color-cream);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 0.813rem;
  color: rgba(255,255,255,0.5);
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  transition: background var(--transition-fast);
}

.footer-social a:hover {
  background: rgba(255,255,255,0.2);
}

/* Footer accordion for mobile */
.footer-accordion-toggle {
  display: none;
}

/* ===== App Download ===== */
.app-download {
  background: var(--color-dark);
  color: var(--color-white);
  padding: 64px 0;
  text-align: center;
  border-radius: var(--radius-xl);
  margin: 80px 0;
}

.app-download h2 {
  margin-bottom: 12px;
}

.app-download p {
  opacity: 0.85;
  margin-bottom: 24px;
  font-size: 1.063rem;
}

.app-buttons {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.app-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 12px 24px;
  background: var(--color-white);
  color: var(--color-dark);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.938rem;
  transition: all var(--transition-base);
}

.app-btn:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

/* ===== Terms Section ===== */
.terms-section {
  background: var(--color-off-white);
  padding: 48px 0;
  font-size: 0.813rem;
  color: var(--color-text-light);
  line-height: 1.8;
}

.terms-section a {
  color: var(--color-primary);
  text-decoration: underline;
}

/* Placeholder images */
.img-placeholder {
  background: linear-gradient(135deg, var(--color-cream-light) 0%, #E8D5B0 50%, var(--color-cream-light) 100%);
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  color: var(--color-cream);
}

.img-placeholder.green {
  background: linear-gradient(135deg, var(--color-primary-light) 0%, var(--color-primary) 100%);
  color: var(--color-white);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  h1 { font-size: 2.75rem; }
  h2 { font-size: 2rem; }

  .grid-2, .feature-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .hero {
    padding: 72px 0 56px;
  }

  .hero h1 {
    font-size: 3rem;
  }

  .hero-image {
    position: relative;
    right: auto;
    top: auto;
    transform: none;
    width: 100%;
    height: 300px;
    border-radius: var(--radius-xl);
    margin-top: 32px;
  }

  .menu-layout {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .menu-sidebar {
    position: static;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    align-items: center;
  }

  .menu-sidebar h3 {
    width: 100%;
    margin: 8px 0 4px;
