  .menu-sidebar a {
    display: inline-block;
    padding: 6px 14px;
    font-size: 0.813rem;
    border: 1px solid var(--color-border-light);
    border-radius: var(--radius-full);
  }

  .locator-layout {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .locator-sidebar {
    max-height: none;
    border-right: none;
    border-bottom: 1px solid var(--color-border-light);
  }

  .locator-map {
    min-height: 400px;
  }

  .tiers-grid {
    grid-template-columns: 1fr;
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
  }

  .partnerships-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .seasonal-card {
    grid-template-columns: 1fr;
    padding: 40px;
  }

  .business-gifting {
    grid-template-columns: 1fr;
    padding: 32px;
  }
}

@media (max-width: 768px) {
  :root {
    --header-height: 60px;
  }

  h1 { font-size: 2.25rem; }
  h2 { font-size: 1.75rem; }
  h3 { font-size: 1.25rem; }

  .section { padding: 48px 0; }
  .section-lg { padding: 72px 0; }

  .container { padding: 0 16px; }

  .grid-3, .steps-grid { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }

  .hero h1 {
    font-size: 2.25rem;
  }

  .hero .hero-subtitle {
    font-size: 1rem;
  }

  .hero-image {
    height: 200px;
  }

  .header-nav {
    display: none;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--color-white);
    flex-direction: column;
    padding: 16px;
    border-bottom: 2px solid var(--color-border-light);
    box-shadow: var(--shadow-md);
  }

  .header-nav.active {
    display: flex;
  }

  .header-nav a {
    padding: 12px 16px;
    border-radius: var(--radius-sm);
  }

  .mobile-menu-btn {
    display: flex;
  }

  .header-actions .btn-outline {
    display: none;
  }

  .seasonal-card {
    padding: 32px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
    margin-bottom: 24px;
  }

  .footer-col {
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }

  .footer-col h4 {
    padding: 16px 0;
    margin: 0;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    user-select: none;
  }

  .footer-col h4::after {
    content: '+';
    font-size: 1.25rem;
    font-weight: 300;
    transition: transform var(--transition-base);
  }

  .footer-col.expanded h4::after {
    content: '−';
  }

  .footer-col .footer-links {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-base);
  }

  .footer-col.expanded .footer-links {
    max-height: 500px;
    padding-bottom: 16px;
  }

  .footer-accordion-toggle {
    display: block;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .redemption-tabs {
    gap: 6px;
  }

  .redemption-tab {
    padding: 10px 16px;
    font-size: 0.813rem;
  }

  .cookie-banner {
    flex-direction: column;
    text-align: center;
    gap: 12px;
  }

  .cookie-banner-actions {
    width: 100%;
    flex-direction: column;
  }

  .cookie-banner-actions .btn {
    width: 100%;
  }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .app-download {
    margin: 48px 0;
    padding: 40px 20px;
  }

  .locator-controls {
    flex-direction: column;
  }

  .carousel-btn {
    width: 36px;
    height: 36px;
  }

  .gift-card {
    min-width: 160px;
  }
}

@media (max-width: 480px) {
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.5rem; }

  .hero { padding: 48px 0 40px; }

  .hero h1 { font-size: 1.75rem; }

  .seasonal-card {
    padding: 24px;
    border-radius: var(--radius-lg);
  }

  .carousel-header h2 {
    font-size: 1.25rem;
  }

  .gift-card {
    min-width: 140px;
  }

  .carousel-track {
    gap: 12px;
  }

  .redemption-panel .star-count {
    font-size: 2.25rem;
  }

  .tier-card {
    padding: 24px 20px;
  }
}

